"""Batched complex128 wavepacket autocorrelation on GPU; original time grids/gates."""
import types
import numpy as np
import torch
from physics_engine.quantum import quantum_revival as cpu


import warp as wp
wp.set_module_options({'enable_backward': False, 'fast_math': False, 'fuse_fp': False})


@wp.kernel
def _autocorr(times: wp.array(dtype=wp.float64),
              spectrum: wp.array2d(dtype=wp.float64),
              result: wp.array(dtype=wp.float64), n: int):
    i = wp.tid()
    real = wp.float64(0.0)
    imag = wp.float64(0.0)
    for j in range(n):
        phase = -spectrum[j, 0] * times[i]
        real = real + spectrum[j, 1] * wp.cos(phase)
        imag = imag + spectrum[j, 1] * wp.sin(phase)
    magnitude = wp.sqrt(real * real + imag * imag)
    result[i] = magnitude * magnitude


def autocorr(t, E1=np.pi**2/cpu.L0**2, anharm=0., device='cuda'):
    times = np.asarray(t, dtype=np.float64)
    spectrum = np.column_stack((cpu.NN**2*E1*(1.+anharm*cpu.NN), cpu.CN2))
    tx = wp.array(times.reshape(-1), dtype=wp.float64, device=device)
    sx = wp.array(spectrum, dtype=wp.float64, device=device)
    out = wp.empty(times.size, dtype=wp.float64, device=device)
    if times.size:
        wp.launch(_autocorr, dim=times.size, inputs=[tx, sx, out, len(spectrum)], device=device)
    return out.numpy().reshape(times.shape)


def revival_time(L=cpu.L0,device='cuda'):
    E1=np.pi**2/L**2;Trev=2*np.pi/E1
    ts=np.linspace(.85*Trev,1.15*Trev,121);A=autocorr(ts,E1,device=device)
    i=int(np.argmax(A))
    if 0<i<len(ts)-1:
        y0,y1,y2=A[i-1],A[i],A[i+1]
        di=.5*(y0-y2)/(y0-2*y1+y2)
        return float(ts[i]+di*(ts[1]-ts[0]))
    return float(ts[i])


def revival_quality(L=cpu.L0,anharm=0.,device='cuda'):
    E1=np.pi**2/L**2;Trev=2*np.pi/E1
    ts=np.linspace(.7*Trev,1.15*Trev,6000)
    return float(autocorr(ts,E1,anharm,device).max())


def main(device='cuda'):
    scope=dict(vars(cpu))
    scope['autocorr']=lambda *a,**kw:autocorr(*a,**kw,device=device)
    scope['revival_time']=lambda *a,**kw:revival_time(*a,**kw,device=device)
    scope['revival_quality']=lambda *a,**kw:revival_quality(*a,**kw,device=device)
    return types.FunctionType(cpu.main.__code__,scope,cpu.main.__name__)()

if __name__=='__main__':raise SystemExit(main())
